from rest_framework import viewsets, permissions, status
from rest_framework.decorators import action
from rest_framework.response import Response
from .models import CatalogProduct

class ProductTranslationPreviewViewSet(viewsets.ViewSet):
    permission_classes = [permissions.IsAuthenticated]

    @action(detail=True, methods=['get'])
    def preview_locale(self, request, pk=None):
        locale = request.query_params.get('locale', 'en')
        # Verify vendor ownership before displaying draft localized copy
        try:
            product = CatalogProduct.objects.get(pk=pk, vendor=request.user.vendor)
        except CatalogProduct.DoesNotExist:
            return Response({"error": "Product not found"}, status=status.HTTP_404_NOT_FOUND)

        desc_field = f"description_{locale}"
        preview_text = getattr(product, desc_field, product.description)
        return Response({"product_id": product.id, "locale": locale, "preview": preview_text})
